     * substrate-portable reads. Cypher-only; cloud mode rejects these.
     *
     * Materialized row list helper — common enough to hoist out of every
     * plugin. Returns an array of plain objects keyed by the RETURN names.
     */
    queryRows(cypher: string, params?: Record<string, unknown>): Promise<Array<Record<string, unknown>>>;

    /**
     * Q1.3 — Invalidate the core read cache.
     *
     * Plugin authors MUST call this after any `executeQuery` that runs
     * a CREATE / MERGE / DELETE / SET / DETACH DELETE — anything that
     * mutates graph state. The `storage.*` mutating methods (upsert /
     * deleteWhere / addEdge / upsertEdge / deleteEdgesWhere) call bumpEpoch
     * internally — plugins on PluginStorage do NOT need to call it manually.
     * The hook remains exposed for the legacy raw-Cypher path.
     *
     * The operation is constant-time (monotonic counter increment) and
     * safe to call multiple times in a transaction.
     */
    bumpEpoch(): void;
}

/**
 * PluginCloudSchemaContext — Q2.2 slice 4. Narrow surface plugins use to
 * provision their owned collections against the Dataplane when the daemon
 * runs in cloud mode. Handed to `registerCloudSchema`.
 *
 * Shape and idempotency mirror DataplaneGraph's core collection push:
 *   - ensureCollection swallows "already exists"/409 errors so the hook is
 *     safe to call on every tenant's first touch, including tenants whose
 *     collections were provisioned in a prior daemon.
 *   - tenantId is resolved per-hook-call by the adapter; plugins never
 *     read AsyncLocalStorage themselves.
 *   - orgId is the ReBAC partitioning key the Lore daemon stamps onto
 *     every record; plugins should include it on collections that carry
 *     org-scoped rows (same convention as lore_node/lore_edge).
 *
 * This is intentionally a different context from `PluginGraphContext`:
 *   - PluginGraphContext is Cypher-oriented (embedded Kùzu shape).
 *   - PluginCloudSchemaContext is Dataplane-CollectionSchema-oriented.
 *
 * A plugin that wants cloud parity implements BOTH hooks with the same
 * logical schema expressed in each backend's vocabulary. The schemas do
 * NOT need to be bit-identical — e.g. Kùzu `INT32` vs Dataplane `int`.
 */
export interface PluginCloudSchemaContext {
    /** Tenant the collections are provisioned for (per-request). */
    readonly tenantId: string;
    /** Org id callers should stamp onto rows + index for ReBAC. */
    readonly orgId: string;
    /**
     * Idempotent schema push. `schema` is a Dataplane CollectionSchema
     * object (`{ name, fields: [{ name, field_type, primary_key?, … }] }`).
     * "already exists" / 409 responses are swallowed. Any other error
     * rejects the promise — the adapter then drops its cached init
     * promise so the next request retries instead of latching a
     * permanent failed state.
     */
    ensureCollection(schema: unknown): Promise<void>;
}

/**
 * EmbeddableNode — What plugins hand back from `contributeReconnectNodes`.
 * The id is already prefixed (e.g. `file:src/foo.ts`, `symbol:abc123`) so
 * a single vector search returns hits across all pillars and the core
 * pass can route results by prefix.
 */
export interface EmbeddableNode {
    id: string;
    text: string;
    metadata: {
        type: string;
        label: string;
        tags: string;
        project: string;
        ecosystem: string;
        updatedAt: string;
        security_scopes: string[];
    };
}

/**
 * ReconnectEdgeProposal — One semantic edge candidate for the plugin to
 * route into the correct REL table. The plugin returns `true` if it
 * accepted the edge; `false` lets the next plugin (or core) try.
 *
 * Both ids carry their pillar prefix so plugins can pattern-match on
 * kind without another lookup.
 */
export interface ReconnectEdgeProposal {
    from: string;
    to: string;
    confidence: number;
    relation: string; // already formatted e.g. "semantic_neighbor:0.842"
}

/**
 * PluginContext — Shared runtime handed to each plugin's tool registrar.
 * Kept intentionally minimal and fully typed. Anything not on here a
 * plugin cannot reach (enforced by the registry).
 */
export interface PluginContext {
    // Service singletons. `unknown` at the interface level to avoid a
    // circular dependency between plugins and engines; plugins that need
    // these cast to the concrete classes they import directly.
    graph: unknown;
    verbatimStore: unknown;
    syncEngine: unknown;
    syncAdapter: unknown | null;
    schemaLoader: unknown;

    // Workspace scope (project + ecosystem autoresolved from cwd).
    scope: { project: string; ecosystem: string };

    // Loreroot. Plugins that manage their own persistence should write
    // beneath `${loreDir}/plugins/${pluginName}/...`.
    loreDir: string;
}

/**
 * PluginUiHints — Phase 3 Mode pill behavior.
 * Clicking a mode pill swaps system prompt, filter preset, and camera focus.
 */
export interface PluginUiHints {
    /** Short label shown on the pill (e.g., "Developer", "Family"). */
    modeLabel: string;
    /** System prompt swap for chat when this mode is active. */
    systemPrompt: string;
    /** Default node types to show (Sigma `nodeReducer` preset). */
    defaultFilterTypes: string[];
    /** Camera focuses on the densest cluster whose nodes carry this tag. */
    cameraFocusTag: string;
}

export interface PluginTelemetryPayload {
    pluginName: string;
    version: string;
    nodeCount: number;
    edgeCount: number;
    tableNames: string[];
}

/**
 * RetentionRule — Phase 5 / C12. A plugin-declared policy for how
 * long its nodes live.
 *
 *   nodeType: which domain node type this rule applies to
 *             (the plugin's own node types — plugins can't regulate others').
 *   condition: how expiry is computed
 *     - 'age'        — nodes older than `ageThresholdDays` expire
 *     - 'tag'        — nodes carrying `tag` expire
 *     - 'predicate'  — plugin implements its own expiry check (future)
 *   action: what to do when a node expires
 *     - 'archive'       — move to cold storage via C11 archive hook
 *     - 'evict-content' — keep the graph node, drop raw content
 *     - 'delete'        — remove the node entirely
 *     - 'keep-forever'  — explicit opt-out (noop)
 */
export interface RetentionRule {
    nodeType: string;
    condition: 'age' | 'tag' | 'predicate';
    ageThresholdDays?: number;
    tag?: string;
    action: 'archive' | 'evict-content' | 'delete' | 'keep-forever';
}

/**
 * PluginIR — A plugin's declared Intermediate Representation.
 *
 * Q1.4 / decision D-D per docs/post_v2_plan.md: "Each plugin invents a
 * narrow IR it serializes into. No generalized CommonMark/OOXML
 * chasing." Making the IR a first-class, declarative field — rather
 * than inferring it from `registerSchema` side effects — lets tooling
 * enumerate a plugin's shape without booting it:
 *
 *   - Scaffolder (`lore scaffold-plugin`) generates a 
... [truncated]

 * NOT need to be bit-identical — e.g. Kùzu `INT32` vs Dataplane `int`.
 */
export interface PluginCloudSchemaContext {
    /** Tenant the collections are provisioned for (per-request). */
    readonly tenantId: string;
    /** Org id callers should stamp onto rows + index for ReBAC. */
    readonly orgId: string;
    /**
     * Idempotent schema push. `schema` is a Dataplane CollectionSchema
     * object (`{ name, fields: [{ name, field_type, primary_key?, … }] }`).
     * "already exists" / 409 responses are swallowed. Any other error
     * rejects the promise — the adapter then drops its cached init
     * promise so the next request retries instead of latching a
     * permanent failed state.
     */
    ensureCollection(schema: unknown): Promise<void>;
}

/**

/**
 * developer/cli.ts — Developer-plugin CLI subcommands.
 *
 * `lore index` and `lore ingest-files` are developer-specific (they
 * reach GitNexus + the CodeFile / CodeSymbol tables the plugin owns).
 * They used to live in core cli/commands.ts, behind
 * `if (pluginRegistry.isActive('developer'))` blocks — exactly the
 * red-flag pattern CLAUDE.md warns against. Option C: move them here
 * and register them through ILorePlugin.registerCliCommands.
 *
 * Both commands reboot their own LocalGraph + PluginRegistry so they
 * work as standalone CLI invocations (no daemon required).
 */

import fs from 'fs';
import path from 'path';
import os from 'os';
import { execSync } from 'child_process';
import { LocalGraph } from '@lore-core/engines/localGraph.js';
import { ConfigManager } from '@lore-core/config/configManager.js';
import { PluginRegistry } from '@lore-core/plugins/registry.js';
import { loreHome } from '@lore-core/config/loreHome.js';
import type { DeveloperApi, IndexResult } from './api.js';

function resolveGraphBasePath(): string {
    return loreHome();
}

async function bootForCli(): Promise<{ graph: LocalGraph; devApi: DeveloperApi | undefined; close: () => Promise<void> }> {
    const basePath = resolveGraphBasePath();
    const loreDir = path.join(basePath, '.lore');
    if (!fs.existsSync(loreDir)) {
        console.error('❌ No .lore/ directory found. Run "lore init" first.');
        process.exit(1);
    }
    const graph = new LocalGraph(basePath);
    const registry = new PluginRegistry(new ConfigManager(loreDir));
    registry.boot();
    await graph.initialize();
    await registry.registerSchemas(graph.createPluginGraphContext());
    const devPlugin = registry.active().find((p) => p.name === 'developer');
    const devApi = devPlugin?.api as DeveloperApi | undefined;
    return { graph, devApi, close: () => graph.close() };
}

function printIndexResult(result: IndexResult): void {
    console.log(`  ✓ ${result.symbolsImported} symbols imported`);
    console.log(`  ✓ ${result.relationsImported} relations imported`);
    if (result.symbolsCleared > 0) {
        console.log(`  ✓ ${result.symbolsCleared} old symbols cleared`);
    }
    console.log(`  ✓ Duration: ${result.durationMs}ms`);
    if (result.errors.length > 0) {
        console.log(`  ⚠ ${result.errors.length} non-fatal errors`);
        for (const error of result.errors.slice(0, 5)) {
            console.log(`    - ${error}`);
        }
        if (result.errors.length > 5) {
            console.log(`    ... and ${result.errors.length - 5} more`);
        }
    }
}

export async function indexCommand(args: string[]): Promise<void> {
    const { graph, devApi, close } = await bootForCli();
    if (!devApi) {
        console.error('❌ `lore index` requires the "developer" plugin. Add "developer" to .lore/config.json plugins[].');
        await close();
        process.exit(1);
    }

    const specificRepo = args[0];
    if (specificRepo) {
        const repoEntry = devApi.getGitNexusRepo(specificRepo);
        if (!repoEntry) {
            console.error(`❌ Repository '${specificRepo}' not found in the code-index registry.`);
            console.error('  Available repos:');
            for (const repo of devApi.listGitNexusRepos()) {
                console.error(`    - ${repo.name} (${repo.stats.nodes} symbols)`);
            }
            await close();
            process.exit(1);
        }
        console.log(`→ Indexing '${specificRepo}' from the code index...`);
        const result = await devApi.importFromGitNexus(repoEntry);
        printIndexResult(result);
    } else {
        const repos = devApi.listGitNexusRepos();
        if (repos.length === 0) {
            console.error('❌ No indexed repos found.');
            console.error('  Run `lore analyze <path>` to build the code index for a repo first.');
            await close();
            process.exit(1);
        }
        console.log(`→ Indexing ${repos.length} repo(s) from the code index...`);
        console.log('');
        for (const repo of repos) {
            console.log(`  ─── ${repo.name} (${repo.stats.nodes} indexed symbols) ───`);
            const result = await devApi.importFromGitNexus(repo);
            printIndexResult(result);
            console.log('');
        }
    }

    const stats = await graph.getStats();
    const devStats = stats.pluginStats?.['developer'] ?? {};
    console.log('═══════════════════════════════════════════════════════════');
    console.log('  Unified Graph Stats:');
    console.log(`    Knowledge: ${stats.nodeCount} nodes, ${stats.edgeCount} edges`);
    console.log(`    Code:      ${devStats['codeSymbolCount'] ?? 0} symbols, ${devStats['codeRelationCount'] ?? 0} relations`);
    console.log('═══════════════════════════════════════════════════════════');

    await close();
}

/**
 * analyzeCommand — `lore analyze <path> [extra args...]`
 *
 * Thin wrapper around the underlying code indexer. Lets users build
 * the code index using only Lore commands, without ever having to
 * learn or type the indexer's name. Streams the indexer's output
 * directly so progress and errors stay visible. Auto-installs the
 * indexer on first run if it's missing.
 *
 * Forwards extra args after <path> to the indexer (e.g.
 * `--embeddings`, `--no-cache`). Exits with the indexer's exit code.
 *
 * Daemon-aware? No — the indexer writes to its own files; Lore reads
 * from there via `lore index` afterwards.
 *
 * Plugin boundary: this command lives in the developer plugin
 * because the indexer (gitnexus) is plugin-owned vocabulary. Core's
 * cli/index.ts dispatches to it via registerCliCommands.
 */
function findIndexerBin(): string | null {
    const candidates = [
        '/opt/homebrew/bin/gitnexus',
        '/usr/local/bin/gitnexus',
        path.join(os.homedir(), '.nvm/versions/node', process.version, 'bin/gitnexus'),
    ];
    for (const c of candidates) {
        if (fs.existsSync(c)) return c;
    }
    return null;
}

export async function analyzeCommand(args: string[]): Promise<void> {
    if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
        console.log('Usage: lore analyze <path> [--embeddings] [--no-cache] [...]');
        console.log('');
        console.log('  Builds the code index for a repository so Lore\'s code_*');
        console.log('  MCP tools (code_query, code_full_context, code_impact, etc.)');
        console.log('  can see the symbols. After analyze finishes, run `lore index`');
        console.log('  to import the symbols into the unified knowledge graph.');
        console.log('');
        console.log('  Extra flags are forwarded to the underlying indexer.');
        console.log('  The indexer is auto-installed on first run if missing.');
        process.exit(args.length === 0 ? 1 : 0);
    }

    let indexerBin = findIndexerBin();
    if (!indexerBin) {
        console.log('  · Code indexer not found. Installing (this may take a minute)...');
        try {
            execSync('npm install -g gitnexus', { stdio: 'inherit' });
        } catch (installError) {
            console.error('');
            console.error(`  ✗ Code indexer install failed: ${(installError as Error).message}`);
            console.error('    You can retry manually: npm install -g gitnexus');
            process.exit(1);
        }
        indexerBin = findIndexerBin();
        if (!indexerBin) {
            console.error('');
            console.error('  ✗ Code indexer install reported success but binary still not on PATH.');
            console.error('    Check your npm global bin directory.');
            process.exit(1);
        }
        console.log('  ✓ Code indexer installed.');
        console.log('');
    }

    try {
        const escaped = args.map((a) => `"${a.replace(/"/g, '\\"')}"`).join(' ');
        execSync(`${indexerBin} analyze ${escaped}`, { stdio: 'inherit' });
    } catch (analyzeError) {
        const exitCode = (analyzeError as { status?: number }).status ?? 1;
        process.exit(exitCode);
    }
}

export async function ingestFilesCommand(_args: string[]): Promise<void> {
    const { devApi, close } = await bootForCli();
    if (!devApi) {
        console.error('  ✗ ingest-files requires the "developer" plugin. Add "developer" to .lore/config.json plugins[].');
        await close();
        return;
    }
    console.log('');
    console.log('  Ingesting files from existing CodeSymbols…');
    const stats = await devApi.ingestFilesFromSymbols();
    console.log(`  ✓ ${stats.filesCreated} CodeFile node(s) synthesized`);
    console.log(`  ✓ ${stats.edgesCreated} FileContains edge(s) created`);
    await close();
    console.log('');
    console.log('  Next: `lore reconnect` to link LoreNode knowledge to these files via semantic similarity.');
}

